import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });
const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));

test('completed nodes affect full graph order and readiness uses current states', () => {
  assert.deepEqual(planJobs([
    job('a', ['z']), job('b'), job('z', [], 'succeeded'), job('c', ['b']),
  ]), { order: ['b', 'c', 'a'], ready: ['a', 'b'], blocked: [] });
});

test('all failed ancestors survive failed and succeeded intermediate nodes', () => {
  assert.deepEqual(planJobs([
    job('z', [], 'failed'), job('a', ['z'], 'failed'),
    job('s', ['a', 'z'], 'succeeded'), job('p', ['s']), job('q', ['p', 'z']),
  ]), { order: [], ready: [], blocked: [
    { id: 'p', causes: ['a', 'z'] }, { id: 'q', causes: ['a', 'z'] },
  ] });
});

test('IDs preserve whitespace, Unicode and prototype names with code-unit sorting', () => {
  const ids = ['é', '😀', '\uE000', 'constructor', '__proto__', ' a ', 'Z', 'a'];
  const spec = Object.freeze(ids.map(id => Object.freeze({
    ...job(id), deps: Object.freeze([]), ignored: true,
  })));
  const sorted = [' a ', 'Z', '__proto__', 'a', 'constructor', 'é', '😀', '\uE000'];
  assert.deepEqual(planJobs(spec), { order: sorted, ready: sorted, blocked: [] });
  assert.deepEqual(spec.map(j => j.id), ids);
});

test('malformed fields, duplicate values, missing references and all cycles fail', () => {
  const invalid = [
    null, {}, 'x', [null], [1], [[]], [{}], [job('')], [job(1)],
    [{ id: 'a', state: 'pending' }], [job('a', null)], [job('a', 'b')],
    [job('a', [null])], [job('a', [''])], [job('a', [1])],
    [job('a', [], 'unknown')], [{ id: 'a', deps: [] }],
    [job('a'), job('a')], [job('a'), job('b', ['a', 'a'])],
    [job('a', ['missing'])], [job('a', ['a'])],
    [job('ok'), job('a', ['b'], 'succeeded'), job('b', ['a'], 'failed')],
  ];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
});

test('CLI emits exactly JSON or reports errors only on stderr with exit 2', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const file = join(dir, 'spec.json');
  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
  try {
    writeFileSync(file, JSON.stringify([job('é')]));
    const success = run([file]);
    assert.equal(success.status, 0);
    assert.equal(success.stderr, '');
    assert.equal(success.stdout, '{"order":["é"],"ready":["é"],"blocked":[]}\n');
    for (const args of [[], [file, file], [join(dir, 'missing')], [dir]]) {
      const failure = run(args);
      assert.equal(failure.status, 2);
      assert.equal(failure.stdout, '');
      assert.ok(failure.stderr.trim());
    }
    for (const content of ['{', '{}', JSON.stringify([job('a', ['a'])])]) {
      writeFileSync(file, content);
      const failure = run([file]);
      assert.equal(failure.status, 2);
      assert.equal(failure.stdout, '');
      assert.ok(failure.stderr.trim());
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('importing the module does not run the CLI', () => {
  const result = spawnSync(process.execPath, ['--input-type=module', '-e',
    `await import(${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)})`,
  ], { encoding: 'utf8' });
  assert.equal(result.status, 0);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, '');
});

